insert into public.clubs (id, domain_id, name, tagline, description, sort) values ('dice', 'technical', 'DICE', 'Roll the idea.', 'Ideas go on the table, get tested against each other and come out as something real. A room for the curious, the stubborn and the slightly reckless.', 0)
insert into public.clubs (id, domain_id, name, tagline, description, sort) values ('dsc', 'technical', 'DSC', 'Learn it. Build it. Share it.', 'A community of student developers who learn in public: study jams, shared projects and the kind of help that starts with ''let me show you''.', 1)
insert into public.clubs (id, domain_id, name, tagline, description, sort) values ('cice', 'technical', 'CICE', 'Signals, circuits, systems.', 'Where electronics meets curiosity. Boards on the bench, oscilloscopes humming and a steady supply of things that blink, buzz or finally work.', 2)
insert into public.clubs (id, domain_id, name, tagline, description, sort) values ('robotics', 'technical', 'Robotics', 'Machines that move.', 'Motors, sensors and a workshop that never really closes. From line followers to arms that pick things up, this is where code learns to push back against gravity.', 3)
insert into public.clubs (id, domain_id, name, tagline, description, sort) values ('coding', 'technical', 'Coding', 'Ship it before sunrise.', 'Late nights, strong opinions about tabs and spaces, and a lot of pull requests. Contests, hack nights and the quiet satisfaction of a green build.', 4)
